#!/usr/bin/env bun
/**
 * PESO CLI — Standalone test runner for debugging.
 *
 * Usage:
 *   bun run src/cli.ts "your prompt here"
 *   bun run src/cli.ts --mode code "implement a retry mechanism"
 *   bun run src/cli.ts --no-llm "fix the bug"
 *   bun run src/cli.ts --debug "explain how auth works"
 *   bun run src/cli.ts --score "write a function"
 *   bun run src/cli.ts --config
 *
 * Env vars:
 *   PESO_DEBUG=1        Verbose pipeline trace
 *   PESO_MODEL=...      Override model
 *   PESO_API_KEY=...    Override API key
 */

import { classify, generateClarifyingQuestions } from './classifier.js'
import { runPipeline } from './enhancer.js'
import { scorePrompt } from './scorer.js'
import { gatherContext, formatContextBlock } from './context-gatherer.js'
import { callSmallModel, resolveConfig, describeConfig } from './llm-client.js'
import { autoSelectTechniques } from './techniques.js'

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
const RESET = '\x1b[0m'
const BOLD = '\x1b[1m'
const DIM = '\x1b[2m'
const GREEN = '\x1b[32m'
const YELLOW = '\x1b[33m'
const CYAN = '\x1b[36m'
const RED = '\x1b[31m'
const MAGENTA = '\x1b[35m'

function log(msg: string) {
  console.log(msg)
}

function header(title: string) {
  log(`\n${BOLD}${CYAN}━━━ ${title} ━━━${RESET}`)
}

function kvLine(key: string, value: string) {
  log(`  ${DIM}${key}:${RESET} ${value}`)
}

function debug(msg: string) {
  if (process.env.PESO_DEBUG === '1' || args.debug) {
    log(`  ${DIM}[debug]${RESET} ${msg}`)
  }
}

// ---------------------------------------------------------------------------
// Arg parsing
// ---------------------------------------------------------------------------
interface CliArgs {
  prompt: string
  mode: 'auto' | 'code' | 'general' | 'creative' | 'research'
  useLlm: boolean
  debug: boolean
  scoreOnly: boolean
  configOnly: boolean
}

function parseArgs(): CliArgs {
  const argv = process.argv.slice(2)
  const result: CliArgs = {
    prompt: '',
    mode: 'auto',
    useLlm: true,
    debug: false,
    scoreOnly: false,
    configOnly: false,
  }

  const promptParts: string[] = []

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]
    if (arg === '--mode' && argv[i + 1]) {
      result.mode = argv[++i] as CliArgs['mode']
    } else if (arg === '--no-llm') {
      result.useLlm = false
    } else if (arg === '--debug' || arg === '-d') {
      result.debug = true
      process.env.PESO_DEBUG = '1'
    } else if (arg === '--score') {
      result.scoreOnly = true
    } else if (arg === '--config') {
      result.configOnly = true
    } else if (arg === '--help' || arg === '-h') {
      printHelp()
      process.exit(0)
    } else {
      promptParts.push(arg)
    }
  }

  result.prompt = promptParts.join(' ')
  return result
}

function printHelp() {
  log(`
${BOLD}PESO CLI — Prompt Engineering Smart Optimizer${RESET}

${BOLD}Usage:${RESET}
  bun run src/cli.ts [options] "your prompt here"

${BOLD}Options:${RESET}
  --mode <mode>    Enhancement mode: auto, code, general, creative, research
  --no-llm         Skip the small-model LLM call (rule-based only)
  --debug, -d      Show full pipeline trace with timing
  --score          Score the prompt without enhancing it
  --config         Show current PESO configuration and exit
  --help, -h       Show this help

${BOLD}Env vars:${RESET}
  PESO_DEBUG=1          Always show debug output
  PESO_MODEL=provider/model   Override the small model
  PESO_API_KEY=sk-...         Override the API key
  PESO_BASE_URL=https://...   Override the API base URL

${BOLD}Examples:${RESET}
  bun run src/cli.ts "fix the login bug"
  bun run src/cli.ts --mode code --debug "implement retry with exponential backoff"
  bun run src/cli.ts --no-llm "explain how authentication works"
  bun run src/cli.ts --score "write a function that processes data"
  bun run src/cli.ts --config
`)
}

// ---------------------------------------------------------------------------
// Enhancement system prompt (same as plugin.ts)
// ---------------------------------------------------------------------------
const ENHANCE_SYSTEM_PROMPT = `You are PESO, a prompt enhancement engine. Your job is to rewrite the user's prompt to be clearer, more specific, and better structured for an AI coding assistant.

Rules:
- Preserve the original intent exactly — do NOT change what the user wants
- Add explicit constraints, output format, and quality criteria where missing
- Move critical instructions to the beginning
- Remove politeness padding (please, could you, etc.)
- Add step-by-step invitation for complex tasks
- If the prompt references potentially outdated info, note that search tools should be used
- Keep the enhanced prompt concise — do not bloat it
- Output ONLY the enhanced prompt, no meta-commentary

You will receive the original prompt along with a context block and classification data.`

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
const args = parseArgs()

async function main() {
  // --config: show config and exit
  if (args.configOnly) {
    header('PESO Configuration')
    try {
      const cfg = resolveConfig()
      kvLine('Provider', cfg.provider)
      kvLine('Model', cfg.model)
      kvLine('API Key', cfg.apiKey ? `${GREEN}✓ configured${RESET}` : `${RED}✗ missing${RESET}`)
      kvLine('Base URL', cfg.baseUrl)
      log('')
      kvLine('PESO_MODEL env', process.env.PESO_MODEL || '(not set)')
      kvLine('PESO_API_KEY env', process.env.PESO_API_KEY ? 'set' : '(not set)')
      kvLine('PESO_BASE_URL env', process.env.PESO_BASE_URL || '(not set)')
    } catch (err) {
      log(`  ${RED}Error: ${err}${RESET}`)
    }
    return
  }

  if (!args.prompt) {
    log(`${RED}Error: No prompt provided.${RESET}`)
    log(`Usage: bun run src/cli.ts "your prompt here"`)
    log(`       bun run src/cli.ts --help`)
    process.exit(1)
  }

  const startTime = Date.now()

  // ── Step 1: Config ──────────────────────────────────────────
  header('Configuration')
  log(`  ${describeConfig()}`)
  kvLine('Mode', args.mode)
  kvLine('LLM rewrite', args.useLlm ? 'enabled' : 'disabled (rule-based only)')

  // ── Step 2: Original prompt ─────────────────────────────────
  header('Original Prompt')
  log(`${DIM}  "${args.prompt}"${RESET}`)

  // ── Step 3: Classification ──────────────────────────────────
  header('Classification')
  const t0 = Date.now()
  const classification = classify(args.prompt, args.mode)
  debug(`classification took ${Date.now() - t0}ms`)

  kvLine('Domain', `${BOLD}${classification.domain}${RESET}`)
  kvLine('Complexity', classification.complexity)
  kvLine('Routing', `${MAGENTA}${classification.suggestedRouting}${RESET}`)
  kvLine('Ambiguity', `${(classification.ambiguityScore * 100).toFixed(0)}%`)
  kvLine('Needs fresh info', classification.needsFreshInfo ? `${YELLOW}yes${RESET}` : 'no')

  if (classification.ambiguousDimensions.length > 0) {
    kvLine('Ambiguous dims', classification.ambiguousDimensions.join(', '))
  }

  if (classification.slots.goal) kvLine('Goal', classification.slots.goal)
  if (classification.slots.constraints.length > 0)
    kvLine('Constraints', classification.slots.constraints.join('; '))
  if (classification.slots.references.length > 0)
    kvLine('References', classification.slots.references.join(', '))
  if (classification.slots.validation.length > 0)
    kvLine('Validation', classification.slots.validation.join('; '))

  // ── Clarify shortcut ────────────────────────────────────────
  if (classification.suggestedRouting === 'clarify') {
    header('Clarification Required')
    const questions = generateClarifyingQuestions(classification)
    questions.forEach((q, i) => log(`  ${YELLOW}${i + 1}. ${q}${RESET}`))
    log(`\n  ${DIM}Refine your prompt and run again.${RESET}`)
    return
  }

  // ── Step 4: Score before ────────────────────────────────────
  header('Score (Before)')
  const scoreBefore = scorePrompt(args.prompt)
  kvLine('Total', `${scoreBefore.total}/10  Grade: ${BOLD}${scoreBefore.grade}${RESET}`)
  kvLine('Rule compliance', `${scoreBefore.rules.score.toFixed(1)}/10`)
  kvLine('Length', `${scoreBefore.lengthScore.toFixed(1)}/2`)
  kvLine('Clarity', `${scoreBefore.clarityScore.toFixed(1)}/2`)
  kvLine('Specificity', `${scoreBefore.specificityScore.toFixed(1)}/2`)

  if (scoreBefore.rules.violations.length > 0) {
    log(`  ${DIM}Violations:${RESET}`)
    for (const v of scoreBefore.rules.violations) {
      log(`    ${YELLOW}[${v.severity}]${RESET} ${v.rule}: ${v.suggestion}`)
    }
  }

  if (args.scoreOnly) {
    return
  }

  // ── Step 5: Context ─────────────────────────────────────────
  header('Context Gathering')
  const t1 = Date.now()
  const ctx = gatherContext()
  const contextBlock = formatContextBlock(ctx, args.prompt)
  debug(`context gathered in ${Date.now() - t1}ms`)

  kvLine('CWD', ctx.cwd)
  kvLine('Git branch', ctx.gitBranch || '(none)')
  kvLine(
    'Changed files',
    ctx.gitChangedFiles.length > 0 ? ctx.gitChangedFiles.join(', ') : '(none)'
  )
  kvLine('Tools', ctx.availableTools.join(', '))
  kvLine('Date', ctx.todayDate)

  if (args.debug) {
    log(`\n  ${DIM}Context block:${RESET}`)
    for (const line of contextBlock.split('\n')) {
      log(`  ${DIM}${line}${RESET}`)
    }
  }

  // ── Step 6: Techniques ──────────────────────────────────────
  header('Techniques (Auto-Selected)')
  const applicableTechniques = autoSelectTechniques(args.prompt, classification.domain)
  if (applicableTechniques.length === 0) {
    log(`  ${DIM}(none applicable)${RESET}`)
  } else {
    for (const t of applicableTechniques) {
      log(`  ${GREEN}✓${RESET} ${BOLD}${t.id}${RESET} — ${t.name}`)
      if (args.debug) {
        log(`    ${DIM}${t.description}${RESET}`)
      }
    }
  }

  // ── Step 7: Rule-based pipeline ─────────────────────────────
  header('Pipeline (Rule-Based)')
  const t2 = Date.now()
  const pipelineResult = runPipeline(args.prompt, classification, {
    domain: classification.domain,
    injectContext: true,
    cwd: ctx.cwd,
    skipStages: [],
  })
  debug(`pipeline took ${Date.now() - t2}ms`)

  for (const stage of pipelineResult.stages) {
    const mark = stage.applied ? `${GREEN}✓${RESET}` : `${DIM}–${RESET}`
    log(`  ${mark} ${BOLD}${stage.stage}${RESET}: ${stage.change}`)
  }

  let enhanced = pipelineResult.enhanced

  // ── Step 8: LLM rewrite ─────────────────────────────────────
  if (args.useLlm) {
    header('LLM Rewrite')
    try {
      const cfg = resolveConfig()
      if (!cfg.apiKey) {
        log(`  ${YELLOW}Skipped — no API key found${RESET}`)
        log(`  ${DIM}Set PESO_API_KEY or ${cfg.provider.toUpperCase()}_API_KEY${RESET}`)
      } else {
        kvLine('Calling', `${cfg.provider}/${cfg.model}`)
        const t3 = Date.now()
        const systemPromptForLlm = pipelineResult.systemPrompt || ENHANCE_SYSTEM_PROMPT
        const userMessage = `<context>\n${contextBlock}\n</context>\n\n<domain>${classification.domain}</domain>\n\n<original-prompt>\n${args.prompt}\n</original-prompt>\n\nRewrite this prompt to be optimally structured for an AI ${classification.domain === 'code' ? 'coding' : classification.domain} assistant.`

        if (args.debug) {
          log(`\n  ${DIM}System prompt:${RESET}`)
          for (const line of systemPromptForLlm.split('\n').slice(0, 5)) {
            log(`  ${DIM}  ${line}${RESET}`)
          }
          log(`  ${DIM}  ...${RESET}`)
          log(`\n  ${DIM}User message (${userMessage.length} chars)${RESET}`)
        }

        const response = await callSmallModel(systemPromptForLlm, userMessage)
        const elapsed = Date.now() - t3
        enhanced = response.text.trim()

        kvLine('Time', `${elapsed}ms`)
        if (response.usage) {
          kvLine(
            'Tokens',
            `${response.usage.promptTokens} in → ${response.usage.completionTokens} out`
          )
        }
        log(`  ${GREEN}✓ LLM rewrite complete${RESET}`)
      }
    } catch (err) {
      log(`  ${RED}✗ LLM error: ${err}${RESET}`)
      log(`  ${DIM}Keeping rule-based result${RESET}`)
    }
  } else {
    header('LLM Rewrite')
    log(`  ${DIM}Skipped (--no-llm)${RESET}`)
  }

  // ── Step 9: Score after ─────────────────────────────────────
  header('Score (After)')
  const scoreAfter = scorePrompt(enhanced)
  kvLine('Total', `${scoreAfter.total}/10  Grade: ${BOLD}${scoreAfter.grade}${RESET}`)

  const delta = scoreAfter.total - scoreBefore.total
  const deltaColor = delta > 0 ? GREEN : delta < 0 ? RED : DIM
  kvLine('Delta', `${deltaColor}${delta >= 0 ? '+' : ''}${delta.toFixed(1)}${RESET}`)

  // ── Step 10: Enhanced prompt ────────────────────────────────
  header('Enhanced Prompt')
  log('')
  log(enhanced)
  log('')

  if (args.debug && pipelineResult.systemPrompt) {
    header('System Prompt (for model)')
    log('')
    log(pipelineResult.systemPrompt)
    log('')
  }

  // ── Summary ─────────────────────────────────────────────────
  const totalTime = Date.now() - startTime
  header('Summary')
  kvLine(
    'Score',
    `${scoreBefore.total}/10 (${scoreBefore.grade}) → ${scoreAfter.total}/10 (${scoreAfter.grade})`
  )
  kvLine('Techniques', `${applicableTechniques.length} applied`)
  kvLine('LLM used', args.useLlm ? 'yes' : 'no')
  kvLine('Total time', `${totalTime}ms`)
  log('')
}

main().catch(err => {
  console.error(`${RED}Fatal: ${err}${RESET}`)
  process.exit(1)
})

/**
 * PESO — OpenCode Plugin Entry Point
 *
 * Transparent prompt enhancement via two hooks:
 *  1. chat.message              — intercepts user prompt, runs pipeline, mutates parts
 *  2. experimental.chat.system.transform — injects PESO system prompt
 *
 * Agent classification:
 *  - Fetches real agent permissions from SDK (client.app.agents())
 *  - Permission-based compass: edit/bash deny→read-only→light; allow→write→full
 *  - Description text used as secondary specificity signal
 *
 * LLM rewrite:
 *  - Uses SDK client.session.prompt() with small model override — no raw HTTP
 *  - Ephemeral session created+deleted per call
 *
 * Opt-out: PESO_AUTO=0
 */

import type { Plugin } from '@opencode-ai/plugin'
import { tool } from '@opencode-ai/plugin'
import type { Agent } from '@opencode-ai/sdk'
import { classify, generateClarifyingQuestions, expandShortPrompt } from './classifier.js'
import { runPipeline, initTechniquePacks } from './enhancer.js'
import type { AgentPermissions } from './enhancer.js'
import { scorePrompt, formatScoreSummary } from './scorer.js'
import { gatherContext, formatContextBlock } from './context-gatherer.js'
import {
  callSmallModel,
  callSmallModelViaSdk,
  resolveConfig,
  resolveModelNameFromSdk,
  describeConfig,
  type SdkClient,
} from './llm-client.js'
import { autoSelectTechniques } from './techniques.js'
import type { Domain } from './classifier.js'
import type { EnhancementResult } from './enhancer.js'

// ---------------------------------------------------------------------------
// Session-scoped cache: chat.message → experimental.chat.system.transform
// ---------------------------------------------------------------------------
const sessionPipelineCache = new Map<string, EnhancementResult>()

// ---------------------------------------------------------------------------
// Agent cache: fetched once on init, refreshed lazily
// ---------------------------------------------------------------------------
let agentCache: Agent[] | null = null

// Model-aware tool ID cache: keyed by "providerID/modelID" (or "" for unknown)
const toolIdsCacheByModel = new Map<string, string[]>()

import { loadPesoConfig, discoverGlobalPacks, type PesoConfig } from './config.js'

type PesoMode = 'on' | 'passive' | 'off'
let pesoMode: PesoMode
let pesoConfig: PesoConfig

/**
 * Resolve the provider/model to use for tool.list() queries.
 *
 * Priority (per approved plan):
 *  1. config.small_model  — explicit cheap/fast model for tooling queries
 *  2. config.model        — top-level model override
 *  3. activeModel         — the actual session model passed from the hook
 *
 * Returns undefined if no model can be determined.
 */
async function resolveToolListModel(
  client: SdkClient,
  activeModel?: { providerID: string; modelID: string }
): Promise<{ providerID: string; modelID: string } | undefined> {
  try {
    const cfg = await client.config.get()
    const cfgData = cfg.data as any

    // Priority 1: small_model
    const smallModelStr: string | undefined =
      typeof cfgData?.small_model === 'string' ? cfgData.small_model : undefined
    if (smallModelStr && smallModelStr.includes('/')) {
      const slash = smallModelStr.indexOf('/')
      return {
        providerID: smallModelStr.substring(0, slash),
        modelID: smallModelStr.substring(slash + 1),
      }
    }

    // Priority 2: top-level model
    const modelStr: string | undefined =
      typeof cfgData?.model === 'string' ? cfgData.model : undefined
    if (modelStr && modelStr.includes('/')) {
      const slash = modelStr.indexOf('/')
      return { providerID: modelStr.substring(0, slash), modelID: modelStr.substring(slash + 1) }
    }
  } catch {
    /* config.get may fail */
  }

  // Priority 3: active session model from hook context
  if (activeModel) return activeModel

  return undefined
}

async function getToolIds(
  client: SdkClient,
  directory?: string,
  activeModel?: { providerID: string; modelID: string }
): Promise<string[]> {
  // Early cache hit: if we already have a result keyed by the incoming model
  const earlyKey = activeModel ? `${activeModel.providerID}/${activeModel.modelID}` : ''
  const earlyCached = toolIdsCacheByModel.get(earlyKey)
  if (earlyCached) return earlyCached

  try {
    // 1. Built-in + plugin tools
    const idsResult = await client.tool.ids({ query: { directory } })
    const ids = new Set<string>(idsResult.data ?? [])

    // 2. MCP server tools — try tool.list() with the resolved model
    let finalKey = earlyKey
    try {
      const toolModel = await resolveToolListModel(client, activeModel)
      if (toolModel) {
        finalKey = `${toolModel.providerID}/${toolModel.modelID}`

        // Check if this resolved key already has a cached result
        const resolvedCached = toolIdsCacheByModel.get(finalKey)
        if (resolvedCached) {
          // Alias the early key too so future calls skip resolution
          if (earlyKey !== finalKey) toolIdsCacheByModel.set(earlyKey, resolvedCached)
          return resolvedCached
        }

        const listResult = await client.tool.list({
          query: { provider: toolModel.providerID, model: toolModel.modelID, directory },
        })
        if (listResult.data) {
          for (const t of listResult.data) ids.add(t.id)
        }
      }
    } catch {
      /* tool.list may fail */
    }

    // 3. Fallback: get MCP server names from status
    try {
      const mcpResult = await client.mcp.status()
      if (mcpResult.data) {
        for (const [name, status] of Object.entries(mcpResult.data)) {
          if ((status as any)?.status === 'connected') {
            ids.add(`[mcp:${name}]`) // marker so user knows which MCP servers are active
          }
        }
      }
    } catch {
      /* mcp.status may fail */
    }

    const result = [...ids].sort()
    // Store under the final resolved key; alias the early key if different
    toolIdsCacheByModel.set(finalKey, result)
    if (earlyKey !== finalKey) toolIdsCacheByModel.set(earlyKey, result)
    return result
  } catch {
    const empty: string[] = []
    toolIdsCacheByModel.set(earlyKey, empty)
    return empty
  }
}

async function getAgents(client: SdkClient): Promise<Agent[]> {
  if (agentCache) return agentCache
  try {
    const result = await client.app.agents()
    agentCache = result.data ?? []
  } catch {
    agentCache = []
  }
  return agentCache
}

/**
 * Extract effective permission for a given type from the permission rules array.
 * Rules are pattern-matched; we look for the wildcard ("*") rule as the baseline.
 * Last matching rule wins (OpenCode evaluates top-to-bottom, last match takes precedence).
 * Returns "deny" as safe default if no matching rule found.
 */
function extractPermission(rules: any[], permissionType: string): 'ask' | 'allow' | 'deny' {
  if (!Array.isArray(rules)) return 'deny'
  let result: 'ask' | 'allow' | 'deny' = 'deny'
  for (const rule of rules) {
    if (rule.permission === permissionType && rule.pattern === '*') {
      result = rule.action as 'ask' | 'allow' | 'deny'
    }
  }
  return result
}

function toAgentPermissions(agent: Agent): AgentPermissions {
  const rules = agent.permission as any
  if (Array.isArray(rules)) {
    return {
      edit: extractPermission(rules, 'edit'),
      bash: extractPermission(rules, 'bash'),
      webfetch: extractPermission(rules, 'webfetch'),
      description: agent.description,
      mode: agent.mode,
    }
  }
  // Fallback: old format (shouldn't happen but just in case)
  const perm = rules ?? ({} as any)
  return {
    edit: perm.edit,
    bash: perm.bash,
    webfetch: perm.webfetch,
    description: agent.description,
    mode: agent.mode,
  }
}

// ---------------------------------------------------------------------------
// Enhancement system prompts — generic fallback + per-domain variants
// ---------------------------------------------------------------------------
const ENHANCE_SYSTEM_PROMPT = `You are PESO, a prompt enhancement engine. Rewrite the user's prompt to be clearer, more specific, and better structured for an AI coding assistant.

Rules:
- Preserve original intent exactly
- Use short, direct words (fix not resolve, show not demonstrate, add not incorporate)
- Never make prompts longer than necessary — concise beats comprehensive
- Add explicit constraints, output format, and quality criteria where missing
- Move critical instructions to the beginning
- Remove politeness padding and filler phrases
- Add step-by-step invitation for complex tasks
- If the workspace has a CLAUDE.md or similar, do not repeat instructions it already covers
- Output ONLY the enhanced prompt, no meta-commentary`

/**
 * Domain-specific rewrite system prompts.
 * Used by enhanceWithSdk() when the pipeline did not produce a system prompt.
 * Each variant focuses on what matters most for that domain.
 */
const DOMAIN_REWRITE_PROMPTS: Record<Domain, string> = {
  code: `You are PESO, a prompt optimizer for AI coding assistants. Rewrite the user's prompt to be:
- Specific about the target file, function, or module
- Clear about the expected output format (code, explanation, diff)
- Explicit about constraints (language, framework, style conventions)
- Front-loaded with the most critical instruction
Rules:
- Preserve original intent exactly — do NOT invent requirements
- Use short, direct words
- Output ONLY the enhanced prompt, no meta-commentary`,

  research: `You are PESO, a prompt optimizer for AI research assistants. Rewrite the user's prompt to be:
- Specific about the depth and scope of research needed
- Clear about what format the answer should take (summary, comparison, pros/cons list)
- Explicit about any sources, time ranges, or domains to focus on
Rules:
- Preserve original intent exactly — do NOT invent requirements
- Output ONLY the enhanced prompt, no meta-commentary`,

  creative: `You are PESO, a prompt optimizer for AI creative assistants. Rewrite the user's prompt to be:
- Clear about tone, style, voice, and intended audience
- Specific about length, format, and structural constraints
- Explicit about what makes a good vs poor output for this task
Rules:
- Preserve original intent exactly — do NOT invent requirements
- Output ONLY the enhanced prompt, no meta-commentary`,

  general: ENHANCE_SYSTEM_PROMPT,
}

// ---------------------------------------------------------------------------
// LLM rewrite via SDK (plugin) or HTTP fallback (tools/CLI)
// ---------------------------------------------------------------------------
async function enhanceWithSdk(
  client: SdkClient,
  prompt: string,
  domain: Domain,
  contextBlock: string,
  systemPrompt: string
): Promise<string> {
  // Use domain-specific system prompt when no pipeline system prompt was provided
  const effectiveSystem = systemPrompt || DOMAIN_REWRITE_PROMPTS[domain] || ENHANCE_SYSTEM_PROMPT
  const userMessage = `<context>\n${contextBlock}\n</context>\n\n<domain>${domain}</domain>\n\n<original-prompt>\n${prompt}\n</original-prompt>\n\nRewrite this prompt for an AI ${domain === 'code' ? 'coding' : domain} assistant.`
  try {
    const result = await callSmallModelViaSdk(client, effectiveSystem, userMessage)
    return result.text.trim() || prompt
  } catch (err) {
    console.error(`[PESO] SDK LLM failed: ${err}`)
    return prompt
  }
}

async function enhanceWithHttp(
  prompt: string,
  domain: Domain,
  contextBlock: string,
  systemPrompt: string
): Promise<string> {
  const effectiveSystem = systemPrompt || DOMAIN_REWRITE_PROMPTS[domain] || ENHANCE_SYSTEM_PROMPT
  const userMessage = `<context>\n${contextBlock}\n</context>\n\n<domain>${domain}</domain>\n\n<original-prompt>\n${prompt}\n</original-prompt>\n\nRewrite this prompt for an AI ${domain === 'code' ? 'coding' : domain} assistant.`
  try {
    const result = await callSmallModel(effectiveSystem, userMessage)
    return result.text.trim() || prompt
  } catch (err) {
    console.error(`[PESO] HTTP LLM failed: ${err}`)
    return prompt
  }
}

/**
 * Quality gate: compare pipeline output vs LLM rewrite and return the winner.
 *
 * Rules:
 *  - LLM rewrite wins if its score >= pipeline score − 0.5 (small tolerance for
 *    cases where the scorer doesn't capture structural improvements)
 *  - If both score lower than the original, keep the original
 *
 * Returns the winning text and a source label for debug output.
 */
function applyQualityGate(
  original: string,
  pipeline: string,
  llmRewrite: string
): {
  text: string
  source: 'llm' | 'pipeline' | 'original'
  scores: { original: number; pipeline: number; llm: number }
} {
  const originalScore = scorePrompt(original).total
  const pipelineScore = scorePrompt(pipeline).total
  const llmScore = scorePrompt(llmRewrite).total

  // LLM wins if it's not meaningfully worse than pipeline
  const winner = llmScore >= pipelineScore - 0.5 ? llmRewrite : pipeline
  const winnerScore = llmScore >= pipelineScore - 0.5 ? llmScore : pipelineScore
  const source = winner === llmRewrite ? 'llm' : 'pipeline'

  // Quality floor: if winner is worse than original, revert
  if (winnerScore < originalScore) {
    return {
      text: original,
      source: 'original',
      scores: { original: originalScore, pipeline: pipelineScore, llm: llmScore },
    }
  }

  return {
    text: winner,
    source,
    scores: { original: originalScore, pipeline: pipelineScore, llm: llmScore },
  }
}

